sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader blurred;
uniform float blur;
uniform float amount;
uniform float softness;
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0 || blur <= 0.0) return src;
    float b = float(blurred.eval(coord).a);
    return src * half(smoothstep(amount - softness * 0.5, amount + softness * 0.5, b));
}
